package org.openjproxy.grpc.server.utils;

import com.openjproxy.grpc.StatementRequest;
import lombok.experimental.UtilityClass;
import org.openjproxy.constants.CommonConstants;
import org.openjproxy.grpc.ProtoConverter;

import java.sql.Statement;
import java.util.Map;

/**
 * Utility class for validating statement request properties and flags.
 * Extracted from StatementServiceImpl to improve modularity.
 */
@UtilityClass
public class StatementRequestValidator {

    /**
     * Checks if the request has auto-generated keys flag set via {@code Statement.RETURN_GENERATED_KEYS}.
     *
     * @param request The statement request
     * @return true if auto-generated keys flag is set
     */
    public boolean hasAutoGeneratedKeysFlag(StatementRequest request) {
        if (request.getPropertiesList().isEmpty()) {
            return false;
        }
        Map<String, Object> properties = ProtoConverter.propertiesFromProto(request.getPropertiesList());
        Integer autoGeneratedKeys = (Integer) properties.get(CommonConstants.STATEMENT_AUTO_GENERATED_KEYS_KEY);
        return autoGeneratedKeys != null && autoGeneratedKeys == Statement.RETURN_GENERATED_KEYS;
    }

    /**
     * Checks if the request requires generated-key tracking — either through
     * {@code RETURN_GENERATED_KEYS}, column index hints, or column name hints.
     * When any of these flags is present the statement must be kept alive in the
     * session so that a subsequent {@code getGeneratedKeys()} call can retrieve
     * the result.
     *
     * @param request The statement request
     * @return true if any generated-key variant is requested
     */
    public boolean requiresGeneratedKeysTracking(StatementRequest request) {
        if (request.getPropertiesList().isEmpty()) {
            return false;
        }
        Map<String, Object> properties = ProtoConverter.propertiesFromProto(request.getPropertiesList());
        Integer autoGeneratedKeys = (Integer) properties.get(CommonConstants.STATEMENT_AUTO_GENERATED_KEYS_KEY);
        return (autoGeneratedKeys != null && autoGeneratedKeys == Statement.RETURN_GENERATED_KEYS)
                || properties.get(CommonConstants.STATEMENT_COLUMN_INDEXES_KEY) != null
                || properties.get(CommonConstants.STATEMENT_COLUMN_NAMES_KEY) != null;
    }

    /**
     * Checks whether the client requested result-set detection for an update.
     *
     * @param request the statement request
     * @return true if executeUpdate should report a result-set reference when JDBC execute produces rows
     */
    public boolean requestsUpdateResultSet(StatementRequest request) {
        if (request.getPropertiesList().isEmpty()) {
            return false;
        }
        Map<String, Object> properties = ProtoConverter.propertiesFromProto(request.getPropertiesList());
        return Boolean.TRUE.equals(properties.get(CommonConstants.STATEMENT_EXECUTE_UPDATE_RESULT_SET_KEY));
    }

    /**
     * Checks if the request is an add batch operation.
     *
     * @param request The statement request
     * @return true if it's an add batch operation
     */
    public boolean isAddBatchOperation(StatementRequest request) {
        if (request.getPropertiesList().isEmpty()) {
            return false;
        }
        Map<String, Object> properties = ProtoConverter.propertiesFromProto(request.getPropertiesList());
        Boolean batchFlag = (Boolean) properties.get(CommonConstants.PREPARED_STATEMENT_ADD_BATCH_FLAG);
        return batchFlag != null && batchFlag;
    }

    /**
     * Returns the number of parameters per set when the request carries several parameter sets.
     *
     * @param request The statement request
     * @return the parameter-set size, or 0 when the request carries a single parameter set
     */
    public int parameterSetSize(StatementRequest request) {
        if (request.getPropertiesList().isEmpty()) {
            return 0;
        }
        Map<String, Object> properties = ProtoConverter.propertiesFromProto(request.getPropertiesList());
        Object size = properties.get(CommonConstants.PREPARED_STATEMENT_PARAMETER_SET_SIZE_KEY);
        return size instanceof Number number ? number.intValue() : 0;
    }
}
